import fs from 'fs';
import path from 'path';
import { TEXT_ROLES } from '@/lib/brand/tokens.generated';

/**
 * Colours live only in web_client/brand/tokens and reach code through the semantic
 * roles (bg-canvas, text-ink, ...) and the generated files. The rest of the frontend
 * must not write a colour literal of its own, nor put opacity on a text role (its
 * contrast is validated in build only at full strength).
 *
 * Generated files declare themselves with the pipeline header, so the exclusion list
 * is never written by hand: a new generated file is skipped as soon as it exists.
 */
const webRoot = path.resolve(__dirname, '..');

const GUARDED = ['app', 'components', 'lib', 'hooks'];
const GENERATED_HEADER = /GENERATED by scripts\/brand\//;
const COLOR_LITERAL = /#[0-9a-f]{3,8}\b|\b(?:rgba?|hsla?|oklch|oklab|lab|lch|hwb)\(/i;
// Built from the generated roles: a text role added later is covered with no edit here.
const TEXT_ROLE_OPACITY = new RegExp(`(?<![\\w-])(?:[\\w-]+:)*text-(?:${TEXT_ROLES.join('|')})\\/\\d+`);

function files(entry: string): string[] {
    const full = path.join(webRoot, entry);
    if (fs.statSync(full).isFile()) return [full];
    return fs
        .readdirSync(full, { withFileTypes: true })
        .filter((e) => e.name !== '__tests__')
        .flatMap((e) => (e.isDirectory() ? files(path.join(entry, e.name)) : [path.join(full, e.name)]))
        .filter((f) => /\.(ts|tsx|css)$/.test(f));
}

const sources = GUARDED.flatMap(files)
    .map((f) => ({ f, rel: path.relative(webRoot, f).replaceAll('\\', '/'), text: fs.readFileSync(f, 'utf8') }))
    .filter(({ text }) => !GENERATED_HEADER.test(text.slice(0, 400)));

// Comment lines paint nothing, and `#133` there is an issue reference, not a colour.
const COMMENT_LINE = /^\s*(?:\/\/|\/\*|\*)/;

function offending(text: string, pattern: RegExp): string[] {
    return text
        .split('\n')
        .map((line, i) => [i + 1, line] as const)
        .filter(([, line]) => !COMMENT_LINE.test(line) && pattern.test(line))
        .map(([n, line]) => `${n}: ${line.trim()}`);
}

describe('no hard-coded colours in the frontend', () => {
    it.each(sources.map((s) => [s.rel, s.text]))('%s', (_rel, text) => {
        expect(offending(text, COLOR_LITERAL)).toEqual([]);
    });
});

describe('no opacity modifier on text roles', () => {
    it.each(sources.map((s) => [s.rel, s.text]))('%s', (_rel, text) => {
        expect(offending(text, TEXT_ROLE_OPACITY)).toEqual([]);
    });
});
